BOOST_AUTO_TEST_CASE(compactsize)
{
    DataStream ss{};
    for (uint64_t i = 1; i <= MAX_SIZE; i *= 2) {
        WriteCompactSize(ss, i - 1);
        WriteCompactSize(ss, i);
    }
    for (uint64_t i = 1; i <= MAX_SIZE; i *= 2) {
        BOOST_CHECK_EQUAL(ReadCompactSize(ss), i - 1);
        BOOST_CHECK_EQUAL(ReadCompactSize(ss), i);
    }
}
